import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.util.Set;
import java.util.TreeSet;

public class CF933C_V2 {
    public static final double EPS = 1e-10;
    static final boolean IS_REMOTE = System.getProperty("ONLINE_JUDGE") != null;
    public static FastScanner scanner;

    public static void main(String[] args) throws FileNotFoundException {
        if (!IS_REMOTE) {
            System.setIn(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF933C.in"));
        }
        scanner = new FastScanner(System.in);
        process();
    }

    public static void process() {
        int n = scanner.nextInt();
        Circle[] circles = new Circle[n];

        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(scanner.nextInt(), scanner.nextInt(), scanner.nextInt());
        }

        if (n == 3 && !Circle.overlap(circles[0], circles[1])) {
            int cnt = 4;
            if (Circle.overlap2(circles[0], circles[2])) {
                cnt++;
            }
            if (Circle.overlap2(circles[1], circles[2])) {
                cnt++;
            }
            System.out.println(cnt);
            return;
        }

        int total = 1;
        TreeSet<Point> points = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            points.clear();
            total++;
            for (int j = 0; j < i; j++) {
                Circle.findIntersections(circles[i], circles[j], points);
            }
            if (points.size() >= 2) {
                total += points.size() - 1;
            }
        }

        System.out.println(total);
    }

    public static double getDistance(Point p1, Point p2) {
        return Math.sqrt(getDistanceSquared(p1, p2));
    }

    public static double getDistanceSquared(Point p1, Point p2) {
        double dx = p1.x - p2.x;
        double dy = p1.y - p2.y;
        return dx * dx + dy * dy;
    }

    public static class Circle {
        Point center;
        int radius;

        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.radius = r;
        }

        public static boolean overlap(Circle a, Circle b) {
            double d = getDistance(a.center, b.center);
            return d <= a.radius + b.radius + EPS && d + EPS >= Math.abs(a.radius - b.radius);
        }

        public static boolean overlap2(Circle a, Circle b) {
            double d = getDistance(a.center, b.center);
            return d < a.radius + b.radius && d > Math.abs(a.radius - b.radius);
        }

        public static void findIntersections(Circle a, Circle b, Set<Point> set) {
            if (!overlap(a, b)) {
                return;
            }

            Line segment = new Line(a.center, b.center);
            double d = getDistance(a.center, b.center);
            double distToMid = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
            Point mid = a.center.shift(segment, distToMid);
            Point dir = segment.getDirection().orthogonal();
            double h = Math.sqrt(a.radius * a.radius - distToMid * distToMid);
            Point pt1 = mid.shift(dir, h);
            Point pt2 = mid.shift(dir, -h);

            set.add(pt1);
            if (!pt2.equals(pt1)) {
                set.add(pt2);
            }
        }
    }

    public static class Point implements Comparable<Point> {
        double x, y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public Point minus(Point other) {
            return new Point(x - other.x, y - other.y);
        }

        public Point shift(Line line, double len) {
            return shift(line.getDirection(), len);
        }

        public Point shift(Point vector, double len) {
            Point unit = vector.unit();
            return plus(unit.scale(len));
        }

        public Point plus(Point other) {
            return new Point(x + other.x, y + other.y);
        }

        public Point scale(double factor) {
            return new Point(x * factor, y * factor);
        }

        public Point unit() {
            double magnitude = Math.sqrt(x * x + y * y);
            return divide(magnitude);
        }

        public Point divide(double divisor) {
            return new Point(x / divisor, y / divisor);
        }

        public Point orthogonal() {
            return new Point(-y, x);
        }

        @Override
        public boolean equals(Object obj) {
            Point other = (Point) obj;
            return Math.abs(x - other.x) < EPS && Math.abs(y - other.y) < EPS;
        }

        @Override
        public int compareTo(Point o) {
            if (equals(o)) {
                return 0;
            }
            if (Math.abs(x - o.x) < EPS) {
                return Double.compare(y, o.y);
            }
            return Double.compare(x, o.x);
        }
    }

    public static class Line {
        Point begin;
        Point finish;

        public Line(Point begin, Point finish) {
            this.begin = begin;
            this.finish = finish;
        }

        public Point getDirection() {
            return finish.minus(begin);
        }

        public double getLength() {
            return getDistance(begin, finish);
        }
    }

    public static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (ptr >= len) {
                try {
                    len = stream.read(buffer);
                } catch (Exception e) {
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }

        public boolean hasNext() {
            int c = read();
            while (c <= 32) c = read();
            return c != -1;
        }
    }
}
